PYTHONDONTWRITEBYTECODE=1 python -B - <<'PY'
import json
from collections import defaultdict
from fractions import Fraction
from itertools import product
from pathlib import Path

from src.C_generators import graded_bracket, normal_order_word

for n in (1, 2, 3):
    path = Path(f"data/C_{n}_structure.json")
    schema = json.loads(path.read_text(encoding="utf-8"))
    basis = schema["basis"]
    labels = basis["odd"] + basis["even"]
    parity = schema["parity"]
    order = {label: index for index, label in enumerate(labels)}
    realizations = schema["generator_realization"]["realizations"]
    polynomials = {}
    for label in labels:
        polynomial = defaultdict(Fraction)
        for term in realizations[label]["standard_form"]:
            coeff = Fraction(term["coeff"])
            for word, factor in normal_order_word(term["words"]).items():
                polynomial[word] += coeff * factor
        polynomials[label] = {word: coeff for word, coeff in polynomial.items() if coeff}

    stored = defaultdict(dict)
    for record in schema["structure_constants"]:
        pair = (record["X"], record["Y"])
        assert order[pair[0]] <= order[pair[1]], (path, pair)
        assert record["Z"] not in stored[pair], (path, record)
        stored[pair][record["Z"]] = Fraction(record["coeff"])

    def serialized_bracket(left, right):
        if order[left] <= order[right]:
            return dict(stored[(left, right)])
        factor = -1 if parity[left] * parity[right] == 0 else 1
        return {label: factor * coeff
                for label, coeff in stored[(right, left)].items()}

    def realize(coefficients):
        result = defaultdict(Fraction)
        for label, coeff in coefficients.items():
            for word, value in polynomials[label].items():
                result[word] += coeff * value
        return {word: value for word, value in result.items() if value}

    for left in labels:
        for right in labels:
            direct = graded_bracket(polynomials[left], polynomials[right],
                                    parity[left], parity[right])
            reverse = graded_bracket(polynomials[right], polynomials[left],
                                     parity[right], parity[left])
            sign = -1 if parity[left] * parity[right] == 0 else 1
            anti = defaultdict(Fraction, direct)
            for word, coeff in reverse.items():
                anti[word] += sign * coeff
            assert not {word: coeff for word, coeff in anti.items() if coeff}, (
                path, "graded anti-symmetry", left, right
            )
            assert direct == realize(serialized_bracket(left, right)), (
                path, "JSON bracket mismatch", left, right
            )

    def bracket(left, right):
        return serialized_bracket(left, right)

    def bracket_element(left, element):
        result = defaultdict(Fraction)
        for inner, coeff in element.items():
            for output, value in bracket(left, inner).items():
                result[output] += coeff * value
