import json
from collections import defaultdict
from fractions import Fraction
from pathlib import Path
import re


def parse_expr(text):
    parts = re.split(r' ([+-]) ', text)
    terms = defaultdict(Fraction)
    for i in range(0, len(parts), 2):
        sign = 1 if i == 0 or parts[i - 1] == '+' else -1
        term = parts[i]
        if i == 0 and term.startswith('-'):
            sign *= -1
            term = term[1:]
        if '*' in term:
            scalar, symbol = term.split('*', 1)
            value = Fraction(scalar)
        else:
            value, symbol = Fraction(1), term
        terms[symbol] += sign * value
    return {k:v for k,v in terms.items() if v}


def reduce_rows(rows, variable_count):
    basis = {}
    for initial in rows:
        row = {j: Fraction(v) for j,v in initial.items() if v}
        while True:
            pivot = min((j for j in row if j < variable_count), default=None)
            if pivot is None:
                break
            if pivot not in basis:
                scale = row[pivot]
                row = {j:v/scale for j,v in row.items() if v}
                basis[pivot] = row
                break
            scale = row[pivot]
            for j,v in basis[pivot].items():
                new = row.get(j, Fraction()) - scale*v
                if new:
                    row[j] = new
                else:
                    row.pop(j, None)
        # If pivot is absent, this row is a zero row after elimination.
    return basis


def numeric_consistent(rows, p, values):
    basis = {}
    inconsistent = None
    for key, row_coeff in rows.items():
        row = {j: Fraction(v) for j,v in row_coeff.items() if v}
        rhs = Fraction(values.get(key, 0))
        while True:
            pivot = min((j for j in row if j < p), default=None)
            if pivot is None:
                if rhs:
                    inconsistent=(key,rhs,row)
                break
            if pivot not in basis:
                scale = row[pivot]
                row={j:v/scale for j,v in row.items() if v}
                rhs /= scale
                basis[pivot]=(row,rhs)
                break
            scale=row[pivot]
            br,bs=basis[pivot]
            for j,v in br.items():
                new=row.get(j,Fraction())-scale*v
                if new: row[j]=new
                else: row.pop(j,None)
            rhs -= scale*bs
        if inconsistent:
            break
    return len(basis), inconsistent

for n in (1,2,3):
    s1=json.loads(Path(f'data/C_{n}_structure.json').read_text())
    s2=json.loads(Path(f'data/C_{n}_gamma.json').read_text())
    s3=json.loads(Path(f'data/C_{n}_evaluated.json').read_text())
    s4=json.loads(Path(f'data/C_{n}_coboundary.json').read_text())
    phi=[x['symbol'] for x in s4['odd_linear_map']['coefficients']]
