    phi_idx={x:i for i,x in enumerate(phi)}
    gb_idx={x:i for i,x in enumerate(gb)}
    mrows=defaultdict(dict); arows=defaultdict(dict)
    for r in s4['coboundary_structure']:
        key=(r['X'],r['Y'],r['Z'])
        mrows[key]={phi_idx[k]:v for k,v in parse_expr(r['coeff']).items()}
    for r in s2['inhomogeneous_deformation']['gamma_structure']:
        key=(r['X'],r['Y'],r['Z'])
        arows[key]={gb_idx[k]:v for k,v in parse_expr(r['coeff']).items()}
    keys=set(mrows)|set(arows)
