            row[len(phi)+j]=row.get(len(phi)+j,Fraction())-v
        aug_rows.append(row)
    aug=reduce_rows(aug_rows,len(phi)+len(gb))
    constraint_rows=[(piv,row) for piv,row in aug.items() if piv>=len(phi)]
    print(f'RANK {n}: phi={len(phi)} gb={len(gb)} noncentral_rows={len([k for k in keys if k[2] != "K"])} rankM={len(m_rank)} rankAug={len(aug)} gb_constraints={len(constraint_rows)}')
    for piv,row in constraint_rows:
        coeffs={gb[piv-len(phi)]:Fraction(1)}
