        # Row equation is sum row[col]*var = 0; scale to output
        print('  constraint:', ' + '.join(f'{v}*{k}' for k,v in coeffs.items() if v), '= 0')
    profile={p:v for prow,vrow in zip(s3['gb_matrix']['parameters'],s3['gb_matrix']['values']) for p,v in zip(prow,vrow)}
    gamma_num={(r['X'],r['Y'],r['Z']):Fraction(r['kappa_coeff']) for r in s3['evaluated_structure_constants'] if Fraction(r['kappa_coeff'])}
    for ignore_k in (False,True):
